// Example of code that triggers voluntary context switches
public void processTasks(List<Task> tasks) {
    for (Task task : tasks) {
        // Blocking I/O forces the thread into WAITING state,
        // triggering a context switch to another runnable thread.
        task.execute(); 

        // Explicitly yielding may trigger a switch if other threads are ready
        Thread.yield(); 
    }
}
